"""Compact APK-derived parameter catalogue for TMT gate controllers.

Generated by reverse-mapping TMT Chow 3.1.4 Android resources and concrete
controller constructors. The data covers all 217 gate controller classes plus
the PS21053C runtime alias. product_type is intentionally not used here.
"""

from __future__ import annotations

import base64
import json
import zlib
from functools import lru_cache
from typing import Final

_DATA_B64: Final = ""

@lru_cache(maxsize=1)
def _catalog() -> dict:
    raw = zlib.decompress(base64.b64decode(_DATA_B64))
    return json.loads(raw.decode("utf-8"))

def get_model_parameter_schema(controller_type: str | None) -> tuple[dict, ...]:
    """Return the exact APK parameter list for a concrete controller model."""
    model = (controller_type or "").strip().upper()
    data = _catalog()
    mapping = data["MODEL_SCHEMAS"].get(model)
    if mapping is None:
        return ()
    family, schema_id = mapping
    rows = data["SCHEMAS"][schema_id]
    labels = data["LABELS"]
    option_sets = data["OPTION_SETS"]
    return tuple(
        {
            "index": index,
            "key": key or f"parameter_{index + 1}",
            "label": labels.get(key, key or f"Parameter {index + 1}"),
            "option_key": option_key,
            "options": tuple(option_sets.get(option_key, ())) if option_key else (),
            "family": family,
            "schema_id": schema_id,
        }
        for index, (key, option_key) in enumerate(rows)
    )

def get_model_parameter_schema_id(controller_type: str | None) -> str | None:
    """Return the deduplicated APK schema id for a model."""
    mapping = _catalog()["MODEL_SCHEMAS"].get((controller_type or "").strip().upper())
    return mapping[1] if mapping else None

def get_model_parameter_count(controller_type: str | None) -> int:
    """Return the number of parameters exposed by the vendor APK for a model."""
    return len(get_model_parameter_schema(controller_type))

def has_model_parameter_schema(controller_type: str | None) -> bool:
    """Return whether the APK has a concrete parameter schema for this model."""
    return bool(get_model_parameter_schema(controller_type))
